"""Create a standalone, filterable, two-tab HTML dashboard (no CDN or server)."""
from pathlib import Path
import json,pandas as pd
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results';OUT=ROOT/'report';OUT.mkdir(exist_ok=True)
parts={k:pd.read_csv(R/(k+'.csv')).fillna('').to_dict(orient='records') for k in ['monthly','monthly_country','segments','cohort_retention','products','country','invoice_status_summary']}
parts['products']=parts['products'][:10]
# The market dropdown exposes all 37 countries; the comparison chart displays top 7.
parts['meta']=json.loads((R/'verified_metrics.json').read_text())
data=json.dumps(parts,ensure_ascii=False,separators=(',',':'))
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online Retail | Revenue, Orders & Customer Cohorts</title>
<style>
:root{--bg:#0C1424;--panel:#18273D;--panel2:#1C3047;--edge:#304761;--white:#F3F7FA;--muted:#ACBDCB;--dim:#7D97AA;--teal:#64DECD;--peach:#FFB18E;--blue:#9FB2FF;--pink:#F18B9D}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 87% -15%,#22274A,transparent 47%),var(--bg);color:var(--white);font-family:Inter,'Segoe UI',Arial,sans-serif}a{color:var(--teal)}.wrap{max-width:1500px;margin:auto;padding:26px 29px 90px}
.top{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--edge);padding:0 0 22px}.brand{font-weight:820;font-size:18px;letter-spacing:.02em}.brand:before{content:'R';font-size:22px;background:var(--teal);color:var(--bg);padding:6px 12px;border-radius:8px;margin-right:12px}.micro{font-size:11px;font-weight:700;letter-spacing:.12em;color:var(--muted);text-transform:uppercase}.badge{border:1px solid #60667C;border-radius:50px;padding:9px 17px;color:var(--peach);font-size:12px;font-weight:750}.eyebrow{margin-top:37px;color:var(--teal);text-transform:uppercase;font-size:13px;letter-spacing:.15em;font-weight:780}h1{font-size:clamp(29px,5vw,59px);line-height:1.06;margin:13px 0 11px;letter-spacing:-.05em}h1 em{font-style:normal;color:var(--peach)}.dek{margin:0 0 21px;color:var(--muted);font-size:16px;max-width:850px;line-height:1.5}
.tabs{display:flex;gap:8px;margin:29px 0 18px}.tab{border:1px solid var(--edge);background:var(--panel);color:var(--muted);border-radius:10px;padding:12px 21px;font-weight:750;cursor:pointer}.tab.active{color:#081624;background:var(--teal);border-color:var(--teal)}.tab:focus-visible,select:focus-visible{outline:3px solid var(--peach)}.hidden{display:none!important}
.controls{display:flex;gap:18px;flex-wrap:wrap;align-items:end;border-radius:12px;background:var(--panel);padding:17px 20px;border:1px solid var(--edge);margin:17px 0 18px}.controls label{display:block;font-weight:750;font-size:12px;color:var(--muted);letter-spacing:.03em}.controls select{display:block;margin-top:8px;border:1px solid var(--edge);border-radius:8px;padding:10px 38px 10px 12px;font:600 14px inherit;color:var(--white);background:var(--bg);min-width:218px}.notice{font-size:12px;color:var(--peach);margin-left:auto;max-width:390px;line-height:1.5}.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.kpi,.panel{border:1px solid var(--edge);background:var(--panel);border-radius:15px;position:relative;overflow:hidden}.kpi{padding:19px 22px 17px;min-height:126px}.kpi:before{content:'';position:absolute;top:0;left:0;width:80px;height:4px;background:var(--teal);border-radius:0 0 8px 0}.kpi:nth-child(3):before{background:var(--peach)}.kpi:nth-child(4):before{background:var(--blue)}.label{font-size:12px;letter-spacing:.045em;color:var(--muted);font-weight:760}.value{font-size:clamp(29px,3vw,45px);font-weight:860;letter-spacing:-.045em;margin:11px 0 3px}.kpi:nth-child(2) .value{color:var(--teal)}.kpi:nth-child(3) .value{color:var(--peach)}.kpi:nth-child(4) .value{color:var(--blue)}.detail{font-size:12px;color:var(--dim);line-height:1.35}.columns{display:grid;grid-template-columns:1.4fr 1fr;gap:14px;margin:15px 0}.columns.equal{grid-template-columns:1fr 1fr}.panel{padding:22px 24px;min-height:290px}.section-no{background:#403848;border-radius:6px;color:var(--peach);font-weight:800;padding:5px 8px;font-size:12px;margin-right:8px}h2{font-size:20px;letter-spacing:-.02em;margin:0 0 6px}.sub{color:var(--muted);font-size:12px;line-height:1.45}.chart{width:100%;height:285px;display:block;margin-top:17px}.legend{display:flex;gap:19px;flex-wrap:wrap;font-size:12px;color:var(--muted);padding-top:9px}.dot{width:9px;height:9px;display:inline-block;border-radius:50%;margin-right:6px}.barrow{display:grid;grid-template-columns:155px 1fr 62px;gap:13px;align-items:center;margin:15px 0;font-size:13px}.bartrack{height:14px;background:var(--edge);border-radius:6px;overflow:hidden}.barfill{height:100%;background:var(--teal);border-radius:6px}.statline{font-size:13px;color:var(--muted);margin:18px 0}.statline strong{color:var(--peach);font-size:17px}.statement{margin:15px 0;border:1px solid #655168;background:#2A293B;border-radius:13px;padding:19px 25px;display:flex;justify-content:space-between;gap:30px;line-height:1.55}.statement strong{color:var(--peach)}.statement .fine{max-width:390px;color:var(--muted);font-size:12px}.table-scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:13px;margin-top:19px}th{text-align:left;text-transform:uppercase;letter-spacing:.035em;font-size:11px;color:var(--muted);padding:10px;border-bottom:1px solid var(--edge);white-space:nowrap}td{padding:10px;border-bottom:1px solid #2B4158;color:var(--white)}td.num{text-align:right;font-variant-numeric:tabular-nums}th.num{text-align:right}.cohort-head{text-align:center!important}.heat{display:inline-block;width:100%;min-width:57px;border-radius:6px;padding:7px 3px;text-align:center;color:#0C1C27;font-weight:750}.info{background:var(--panel2);border-left:3px solid var(--peach);padding:17px 22px;margin:20px 0;font-size:14px;color:var(--muted);line-height:1.55}.info strong{color:var(--white)}footer{font-size:12px;color:var(--dim);line-height:1.8;border-top:1px solid var(--edge);padding-top:19px;margin-top:28px}@media(max-width:950px){.grid4{grid-template-columns:repeat(2,1fr)}.columns,.columns.equal{grid-template-columns:1fr}.statement{display:block}.notice{margin:0}.wrap{padding:15px}.barrow{grid-template-columns:120px 1fr 48px}.panel{padding:15px}}@media(max-width:520px){.grid4{grid-template-columns:1fr}.brand{font-size:12px}.badge{font-size:10px}.tab{flex:1;padding:12px 6px;font-size:12px}}
</style></head><body><main class="wrap"><header class="top"><div class="brand">RETAIL / INTELLIGENCE</div><div class="badge">HISTORICAL DATA · VERIFIED EXTRACT</div></header><div class="eyebrow">Online retail / investigative case study</div><h1>More orders.<br><em>Not bigger baskets.</em></h1><p class="dek">The autumn sales increase looked impressive. I tested whether people were ordering more often or spending more per order, then followed the customer behaviour behind those numbers.</p>
<nav class="tabs" aria-label="Report pages"><button class="tab active" id="btSales" aria-controls="pgSales" aria-selected="true" onclick="page('Sales')">01 / Sales & markets</button><button class="tab" id="btCustomer" aria-controls="pgCustomer" aria-selected="false" onclick="page('Customer')">02 / Customers & cohorts</button></nav>
<section id="pgSales"><div class="controls"><label>Market<select id="market"><option value="All markets">All markets</option><option value="Outside UK">Outside UK</option></select></label><label>Time window<select id="window"><option value="jan-nov">Jan–Nov 2011 (full months)</option><option value="sep-nov">Sep–Nov 2011</option><option value="all">Full observed extract*</option></select></label><div class="notice">Market and time filters apply to the sales page. Other tabs use separately defined measures.</div></div>
<div class="grid4"><article class="kpi"><div class="label">OBSERVED SALES VALUE</div><div id="sales" class="value">—</div><div class="detail">Assumed GBP; no costs or refunds in this extract</div></article><article class="kpi"><div class="label">INVOICES</div><div class="value" id="orders">—</div><div class="detail">Distinct observed invoice numbers</div></article><article class="kpi"><div class="label">AVERAGE ORDER VALUE</div><div class="value" id="aov">—</div><div class="detail">Recorded sales / recorded invoices</div></article><article class="kpi"><div class="label">REVENUE FROM LATER-MONTH BUYERS</div><div class="value" id="returning">—</div><div class="detail">Not lifetime-new vs returning; first observed in extract</div></article></div>
<div class="columns"><article class="panel"><h2><span class="section-no">01</span>Monthly sales and invoice counts</h2><div class="sub" id="trendSubtitle">Jan–Nov 2011 · recorded sales (bars) and orders (line)</div><div id="trendChart" class="chart"></div><div class="legend"><span><span class="dot" style="background:var(--teal)"></span>Sales value (£k)*</span><span><span class="dot" style="background:var(--peach)"></span>Orders (right axis)</span></div></article><article class="panel"><h2><span class="section-no">02</span>Order count vs basket value</h2><div class="sub">Compare the two complete months: September and November 2011</div><div id="compare" style="margin-top:24px"></div><div class="info">A higher recorded sales total does not automatically mean customers spent more per order. The invoice-count and average-order-value components can move in opposite directions.</div></article></div>
<div class="columns equal"><article class="panel"><h2><span class="section-no">03</span>Where the recorded sales came from</h2><div class="sub">Country summary across the full extract. This chart is intentionally not affected by page filters.</div><div id="countryRows" style="margin-top:20px"></div></article><article class="panel"><h2><span class="section-no">04</span>Products generating the most sales</h2><div class="sub">Stock-code ranking across the full extract; quantity and revenue answer different questions.</div><div class="table-scroll"><table id="productsTbl"><thead><tr><th>Product</th><th class="num">Units</th><th class="num">Sales*</th></tr></thead><tbody></tbody></table></div></article></div>
<div class="statement"><div><strong>Initial conclusion:</strong> from September to November 2011, monthly sales rose 34.1%. Invoices rose 53.0%, while average order value fell 12.4%. The increase in order count is the principal arithmetic contributor.</div><div class="fine">Do not treat December 2011 as a complete month. Geography is skewed toward the UK and the file excludes non-positive quantities/prices.</div></div></section>
<section id="pgCustomer" class="hidden"><div class="info"><strong>Different denominator, different question:</strong> two-or-more-invoice customers are grouped with knowledge of their entire observed history. The cohort matrix below instead asks whether customers purchased in a subsequent calendar month.</div>
<div class="grid4"><article class="kpi"><div class="label">OBSERVED CUSTOMERS</div><div class="value">4,261</div><div class="detail">Known customer IDs present in the filtered extract</div></article><article class="kpi"><div class="label">CUSTOMERS WITH 2+ INVOICES</div><div class="value">2,773</div><div class="detail">65.1% of observed customers</div></article><article class="kpi"><div class="label">SHARE OF RECORDED SALES</div><div class="value">92.1%</div><div class="detail">Revenue attributable to this retrospective group</div></article><article class="kpi"><div class="label">CHAMPION GROUP'S SALES</div><div class="value">54.8%</div><div class="detail">Rule-based end-of-observation segment</div></article></div>
<div class="columns equal"><article class="panel"><h2><span class="section-no">05</span>Customer segmentation</h2><div class="sub">Heuristics: recency as of 10 Dec 2011, invoice count across extract, historical spend; not a churn model.</div><div id="segmentsRows" style="margin-top:27px"></div></article><article class="panel"><h2><span class="section-no">06</span>What happens after first observation?</h2><div class="sub">Percentage returning in the respective later month, not cumulative retention. Earlier cohorts only for fair follow-up.</div><div class="table-scroll"><table id="cohortsTbl"><thead><tr><th>First observed</th><th class="cohort-head">+1</th><th class="cohort-head">+2</th><th class="cohort-head">+3</th><th class="cohort-head">+4</th></tr></thead><tbody></tbody></table></div></article></div><div class="statement"><div><strong>Why both views?</strong> 92.1% is the observed sales share of people who placed multiple invoices at some point. It does not measure whether any particular monthly cohort will return.</div><div class="fine">The cohort assignment is based on customers' first appearance in this file, not proven first-ever purchase. Month-end truncation and seasonal purchasing can affect retention comparisons.</div></div></section>
<footer><strong>Scope:</strong> Analysis of the supplied 384,721-row, 13-column positive-transaction extract. Mixed-format invoice dates were repaired and derived calendar fields recomputed. Assumed pounds sterling based on the underlying UK-retail context; currency is not stated in the CSV. No profit, cancellations or return-rate analysis is possible. Static, self-contained dashboard built from actual aggregated results, not a Power BI deployment. See the project README for transformation and sensitivity checks.</footer>
</main><script>const DATA=__EMBED__;
const $=id=>document.getElementById(id),money=v=>'£'+Math.round(v).toLocaleString('en-GB'),short=v=>v>=1e6?'£'+(v/1e6).toFixed(2)+'m':v>=1000?'£'+(v/1000).toFixed(1)+'k':money(v);
const labels={'2010-12':'Dec 10','2011-01':'Jan','2011-02':'Feb','2011-03':'Mar','2011-04':'Apr','2011-05':'May','2011-06':'Jun','2011-07':'Jul','2011-08':'Aug','2011-09':'Sep','2011-10':'Oct','2011-11':'Nov','2011-12':'Dec*'};
function page(k){for (const x of ['Sales','Customer']){$('pg'+x).classList.toggle('hidden',x!==k);$('bt'+x).classList.toggle('active',x===k);$('bt'+x).setAttribute('aria-selected',x===k?'true':'false')} }
function period(v){return v==='jan-nov'?DATA.monthly.filter(r=>r.Month>='2011-01'&&r.Month<='2011-11').map(r=>r.Month):v==='sep-nov'?['2011-09','2011-10','2011-11']:DATA.monthly.map(r=>r.Month)}
function drawTrend(rows){const W=750,H=260,L=50,R=45,T=21,B=39,bw=W-L-R,n=rows.length,x=i=>L+(i+.5)*bw/n,sY=v=>H-B-v/Math.max(1,Math.ceil(Math.max(...rows.map(r=>r.Revenue))/100000)*100000)*(H-B-T),oY=v=>H-B-v/Math.max(1,Math.ceil(Math.max(...rows.map(r=>r.Orders))/500)*500)*(H-B-T);const maxv=Math.ceil(Math.max(...rows.map(r=>r.Revenue))/100000)*100;let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Monthly sales bars in thousands and invoice count line" style="width:100%;height:100%">`;for(let i=0;i<5;i++){let yy=T+i*(H-T-B)/4;s+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#34465B" stroke-width="1"/><text x="${L-7}" y="${yy+4}" text-anchor="end" fill="#A0B4C4" font-size="11">${Math.round(maxv*(4-i)/4)}k</text>`}const step=bw/n;rows.forEach((r,i)=>{let yy=sY(r.Revenue);s+=`<rect x="${x(i)-Math.min(19,step*.29)}" y="${yy}" width="${Math.min(38,step*.58)}" height="${H-B-yy}" fill="#64DECD" opacity=".76" rx="3"><title>${r.Month}: ${money(r.Revenue)}, ${r.Orders} invoices</title></rect><text x="${x(i)}" y="${H-14}" fill="#B6CBD3" text-anchor="middle" font-size="${n>11?10:12}">${labels[r.Month]||r.Month}</text>`});let path=rows.map((r,i)=>(i?'L':'M')+x(i).toFixed(1)+','+oY(r.Orders).toFixed(1)).join(' ');s+=`<path d="${path}" fill="none" stroke="#FFB18E" stroke-width="3"/>`;rows.forEach((r,i)=>s+=`<circle cx="${x(i)}" cy="${oY(r.Orders)}" r="4" fill="#FFB18E"><title>${r.Month}: ${r.Orders} invoices</title></circle>`);s+=`<text x="${W-5}" y="14" text-anchor="end" fill="#FFB18E" font-size="11">Orders · right scale</text><text x="${W-5}" y="${T+9}" text-anchor="end" fill="#FFB18E" font-size="12">${Math.ceil(Math.max(...rows.map(r=>r.Orders))/500)*500}</text></svg>`;return s}
function compareBars(){const a=DATA.monthly.find(r=>r.Month==='2011-09'),b=DATA.monthly.find(r=>r.Month==='2011-11');const blocks=[['INVOICES',a.Orders,b.Orders,n=>n.toLocaleString('en-GB')],['AVERAGE ORDER VALUE',a.AOV,b.AOV,n=>money(n)]];return blocks.map(([name,sep,nov,f])=>{const max=Math.max(sep,nov)*1.1;return `<div style="margin:25px 0"><div class="micro" style="margin-bottom:9px">${name}</div>${[['SEP',sep,'var(--blue)'],['NOV',nov,'var(--teal)']].map(([mon,val,color])=>`<div class="barrow" style="grid-template-columns:40px 1fr 95px;margin:9px 0"><span>${mon}</span><span class="bartrack"><span class="barfill" style="display:block;width:${(val/max*100).toFixed(1)}%;background:${color}"></span></span><strong style="text-align:right">${f(val)}</strong></div>`).join('')}<div style="color:var(--peach);font-size:14px;font-weight:750;margin-top:7px">Change ${(100*(nov/sep-1))>=0?'+':''}${(100*(nov/sep-1)).toFixed(1)}%</div></div>`}).join('')}
function update(){let m=$('market').value,months=period($('window').value);let rows=months.map(month=>{let set=DATA.monthly_country.filter(r=>r.Month===month&&(m==='All markets'||(m==='Outside UK'?r.Country!=='United Kingdom':r.Country===m)));return {Month:month,Revenue:set.reduce((v,r)=>v+r.Revenue,0),Orders:set.reduce((v,r)=>v+r.Orders,0),ReturningLaterMonthRevenue:set.reduce((v,r)=>v+r.ReturningLaterMonthRevenue,0)}});let rev=rows.reduce((a,b)=>a+b.Revenue,0),ord=rows.reduce((a,b)=>a+b.Orders,0),later=rows.reduce((a,b)=>a+b.ReturningLaterMonthRevenue,0);$('sales').textContent=short(rev);$('orders').textContent=ord.toLocaleString('en-GB');$('aov').textContent=ord?money(rev/ord):'—';$('returning').textContent=rev?(100*later/rev).toFixed(1)+'%':'—';$('trendChart').innerHTML=drawTrend(rows);$('trendSubtitle').textContent=m+' · observed period · sales (bars) and orders (line)';$('compare').innerHTML=compareBars();}
const cs=DATA.country;const max=cs[0].Revenue;$('countryRows').innerHTML=cs.slice(0,7).map(r=>`<div class="barrow"><span>${r.Country==='United Kingdom'?'United Kingdom':r.Country}</span><span class="bartrack"><span class="barfill" style="display:block;width:${(r.Revenue/max*100).toFixed(1)}%;background:${r.Country==='United Kingdom'?'var(--teal)':'var(--blue)'}"></span></span><strong>${r.SharePct.toFixed(1)}%</strong></div>`).join('');$('productsTbl').querySelector('tbody').innerHTML=DATA.products.slice(0,6).map(r=>`<tr><td>${r.Description}</td><td class="num">${r.Units.toLocaleString('en-GB')}</td><td class="num">${short(r.Revenue)}</td></tr>`).join('');
const seg=DATA.segments.sort((a,b)=>b.RevenueSharePct-a.RevenueSharePct);$('segmentsRows').innerHTML=seg.map(r=>`<div class="barrow"><span>${r.Segment}</span><span class="bartrack"><span class="barfill" style="display:block;width:${(r.RevenueSharePct/60*100).toFixed(1)}%;background:${r.Segment==='Champions'?'var(--teal)':'var(--blue)'}"></span></span><strong>${r.RevenueSharePct.toFixed(1)}%</strong></div>`).join('');
let chosen=['2010-12','2011-01','2011-02','2011-03','2011-04','2011-05','2011-06','2011-07'];$('cohortsTbl').querySelector('tbody').innerHTML=chosen.map(month=>`<tr><td>${month}</td>${[1,2,3,4].map(i=>{let r=DATA.cohort_retention.find(x=>x.FirstObservedMonth===month&&x.CohortIndex===i),v=r?r.RetentionPct:0;return `<td class="num"><span class="heat" style="background:rgba(100,222,205,${(0.13+v/100*.8).toFixed(2)});color:${v>32?'#081C25':'#F1F8FF'}">${v.toFixed(1)}%</span></td>`}).join('')}</tr>`).join('');
for(let id of ['market','window'])$(id).addEventListener('change',update);for(let country of DATA.country.map(r=>r.Country)){let el=document.createElement('option');el.value=country;el.textContent=country;$('market').appendChild(el)}update();
</script></body></html>'''
html=html.replace('__EMBED__',data)
(OUT/'interactive_dashboard.html').write_text(html,encoding='utf-8')
print('Standalone offline dashboard bytes:',len(html.encode('utf-8')))
